  verify t against Approved(t)
}

fn watched(t: Text) -> Inferred<Text> {
  delegate A.s(t) supervise escalate(human, role: owner_role)
}

fn outer(t: Text) -> Text {
  raise(t)
}

fn helper(t: Text) -> Inferred<Text> {
  delegate A.s(t)
}

